typedef float rational_t;
typedef rational_t time_value_t;

extern "C" float sqrtf(float);
#define __fsqrt(f) sqrtf(f)

class vector3d
{
public:
  rational_t x, y, z;
  vector3d operator*(rational_t b) const
  {
    vector3d r = { x*b, y*b, z*b };
    return r;
  }
};

class physical_interface
{
public:
  enum force_type
  {
    CONTINUOUS=0,
    INSTANT=1
  };
  rational_t get_mass() const;
  virtual void apply_force_increment(const vector3d& f, force_type ft, const vector3d& loc, int mods=0);
  void apply_force_increment(const vector3d& f, force_type ft)
  {
    apply_force_increment(f, ft, *(const vector3d*)0, 0);
  }
};

class entity
{
public:
  virtual void get_velocity(vector3d* target) const;
  bool has_physical_ifc() const;
  physical_interface* physical_ifc() const;
};

class os_developer_options
{
public:
  static os_developer_options* inst();
  bool get_gravity_enabled() const;
};

class character_hard_attributes;

class motion_object
{
public:
  virtual ~motion_object();
  virtual bool is_active() const;
  virtual void set_active(bool yorn);
protected:
  bool active;
  bool locked;
};

class force_generator : public motion_object
{
public:
  virtual void frame_advance(time_value_t time_inc)=0;
};

class linear_force_generator : public force_generator
{
protected:
  vector3d dir;
  entity* ent;
};

class launcher : public linear_force_generator
{
public:
  virtual void frame_advance(time_value_t time_inc);
protected:
  bool doit;
  character_hard_attributes* att;
  rational_t (*att_get_launch_height)(character_hard_attributes*);
};

extern rational_t g_gravity;

void launcher::frame_advance(time_value_t time_inc)
  {
  if (doit)
    {
    vector3d vel;
    rational_t impulse_accel = __fsqrt((*att_get_launch_height)(att)*g_gravity*2);
    if (os_developer_options::inst()->get_gravity_enabled())
      {
      ent->get_velocity(&vel);
      if (vel.y>0)
        impulse_accel -= vel.y;
      if (impulse_accel<0) impulse_accel = 0;
      }

      if(ent->has_physical_ifc())
      {
        rational_t impulse = impulse_accel*ent->physical_ifc()->get_mass();
        ent->physical_ifc()->apply_force_increment(dir*impulse, physical_interface::INSTANT);
      }
